mapper.select:
select id, seller_id, title, description, category_code, condition_code, defects,
       start_price, duration_hours, scheduled_start, is_auto_downgrade,
       seckill_price, shop_price, chat_enabled, status, rejection_reason,
       gmt_create, gmt_modified, is_deleted, version
from listing
where seller_id = #{sellerId} and is_deleted = false
and status = #{status}
and id < #{cursor}
order by id desc
limit #{limit}


where o.dispute_status is not null
  and o.is_deleted = false
  and (#{privileged} = true or o.buyer_id = #{userId} or o.seller_id = #{userId})
and o.id < #{cursor}
order by o.id desc
limit #{limit}
